			c[i] = (short)Integer.parseInt((s.split(" ",0))[2]);
		}
		for(short i=0;i<N;i++){
			if(isRightTriangle(a[i],b[i],c[i])){System.out.println("YES");}
			else{System.out.println("NO");}
		}
    }
	public static boolean isRightTriangle(int a, int b, int c){
		return (a>=b&&a>=c&&a*a==b*b+c*c)
			||(b>=c&&b>=a&&b*b==c*c+a*a)
			||(c>=a&&c>=b&&c*c==a*a+b*b);
	}
}

