		num=l;
		while(num%s!=0){
			num=num+l;
		}
		return num;
	}

	public static long koyaku(long x, long y){
		long l,s;
		if(x>=y){l=x;s=y;}
		else{l=y;s=x;}

		if(l%s==0) return s;
		return koyaku(s,l%s);
	}

}

