  }
  static void insertionSort(int[] A, int N){
    for(int i = 1; i < N; i++){
      int tmp = A[i];
      int j;
      for (j = i; j > 0 && A[j-1] > tmp; j--)
        A[j] = A[j - 1];
      A[j] = tmp;
      show(A, N);
    }
  }
  static void show(int[] A, int N){
    System.out.print(A[0]);
    for (int i = 1; i < N; i++){
      System.out.print(" " + A[i]);
    }
    System.out.println();
  }
}

