			if (isPrime(num)) {
				cnt++;
			}
		}

		System.out.println(cnt);
	}

	private static boolean isPrime(int x) {
		if (x == 2) {
			return true;
		}

		if (x < 2 || x % 2 == 0) {
			return false;
		}

		int i = 3;

		while (i <= Math.sqrt(x)) {
			if (x % i == 0) {
				return false;
			}
			i = i + 2;
		}
		return true;
	}
}

