			else if (num % 2 ==0){
				ans--;
				continue;
			}
			for (int j=3; j<=Math.sqrt(num); j+=2){
				if (num%j==0) {
					ans--;
					break;
				}
			}
		}
		System.out.println(ans);
	}
}

