		boolean flag=true;
		int i=0;
		int count=0;
		while(flag){
			flag=false;
			for(int j=n-1;j>i;j--){
				if(a[j]<a[j-1]){
					int temp=a[j];
					a[j]=a[j-1];
					a[j-1]=temp;
					flag=true;
					count++;
				}
			}
			i++;
		}
		return count;
	}

}

