class Poppin {
	int top = 0;
	int[] a;

	public Poppin(int n) {
		a = new int[n];
	}

	void add(int x) {
		top++;
		a[top] = x;

	}

	int pop() {
		int x = a[top];
		top--;
		return x;
	}
}

