            totalTime += tmp;
        }
        int sumTime = 0;
        Deque<String> finishName = new ArrayDeque<>();
        Deque<Integer> finishTime = new ArrayDeque<>();
        while(sumTime != totalTime){
            int t = time.poll();
            if(t <= q){
                sumTime += t;
                finishTime.add(sumTime);
                finishName.add(name.poll());
            }else{
                sumTime += q;
                time.add(t - q);
                name.add(name.poll());
            }
        }
