		if((x-r)<0){
			leftside=true;
		}

		if(W<(x+r)){
			rightside=true;
		}

		if(H<(y+r)){
			upside=true;
		}

		if((y-r)<0){
			downside=true;
		}

		if(leftside||rightside||upside||downside){
			System.out.println("No");
		}else{
			System.out.println("Yes");
		}

	}
}

