class Rectangle {
    private int hight;
    private int wide;

    Rectangle(int hight, int wide){
        this.hight = hight;
        this.wide = wide;
    }

    String makeFrame(String symbol, String dot) {
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < hight; i++) {
            for (int j = 0; j < wide; j++) {
                if (i == 0 || i == (hight - 1) || j == 0 || j == (wide - 1)) {
                    sb.append(symbol);
                } else {
                    sb.append(dot);
                }
            }
            sb.append("\n");
        }
        sb.append("\n");

        return sb.toString();
    }

    String makeRectangle(String symbol){
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < hight; i++) {
            for (int j = 0; j < wide; j++) {
                sb.append(symbol);
            }
            sb.append("\n");
        }
        sb.append("\n");

        return sb.toString();
    }

    String makeCheck (String symbol, String dot) {
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < hight; i++) {
            for (int j = 0; j < wide; j++) {
                if (j % 2 == 0 && i % 2 == 0) {
                    sb.append(symbol);
                } else if (j % 2 == 1 && i % 2 == 1) {
                    sb.append(symbol);
                } else {
                    sb.append(dot);
                }
            }
            sb.append("\n");
        }
        sb.append("\n");

        return sb.toString();
    }
}

