				if ((i + 1) % 2 == 0) {
					if ((j + 1) % 2 == 0) {
						System.out.print("#");
					} else {
						System.out.print(".");
					}					
				} else {
					if ((j + 1) % 2 == 0) {
						System.out.print(".");
					} else {
						System.out.print("#");
					}
				}
			}
			System.out.println();
		}
