import java.io.*;
public class Main {
	public static void main(String[] args) throws IOException{
		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
		String line = reader.readLine();
		int n = Integer.parseInt(line);
		int x[][] = new int[n][4];
		int y[][][] = new int[4][3][10];
		for(int i = 0; i < 4; i++){
			for(int j = 0; j < 3; j++){
				for(int k = 0; k < 10; k++){
					y[i][j][k] = 0;
				}
			}
		}
		for(int l = 0; l < n; l++){
			String line1 = reader.readLine();
			String[] sarray = line1.split(" ", -1);
			for(int m = 0; m < 4; m++){
				x[l][m] = Integer.parseInt(sarray[m]);
			}
			y[x[l][0] - 1][x[l][1] - 1][x[l][2] - 1] += x[l][3];
		}
		for(int p = 0; p < 4; p++){
			for(int q = 0; q < 3; q++){
				for(int r = 0; r < 10; r++){
					System.out.print(" " + y[p][q][r]);
				}
				System.out.println();
			}
			if(p < 3){
				System.out.println("####################");
			}
		}
	}
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args){
		Scanner scan=new Scanner(System.in);

		int a[][]=new int[16][10];
		int i,j;

		//初期化
		for(i=0;i<16;i++){
			for(j=0;j<10;j++){
				if(i%4==0)a[i][j]=-1;
				else a[i][j]=0;
			}
		}

		int n=scan.nextInt();
		for(i=0;i<n;i++){
			int b=scan.nextInt();
			int f=scan.nextInt();
			int r=scan.nextInt();
			int v=scan.nextInt();

			a[4*(b-1)+f][r-1]+=v;
		}

		for(i=1;i<16;i++){
			for(j=0;j<10;j++){
				if(a[i][j]==-1)System.out.print("##");
				else System.out.printf(" %d",a[i][j]);
			}
			System.out.println();
		}
	}
}

