class Room {

	private int residents;

	Room(int residents) {	
		this.residents	= residents;
	}

	public int getResidents() {
		return this.residents;
	}

	public void setResidents(int n) {
		this.residents += n;
		if (this.residents > 9) this.residents = 9;
		if (this.residents < 0) this.residents = 0;
	}
}

