				B[k][p] = b;


			}
		}

		//Aの横とBの縦が同じことに注意する

		long sum = 0;
		long seki = 0;



		for(int q = 0;q < n;q++) {

			for(int r = 0;r < l;r++) {

				for(int s = 0;s < m;s++) {

					//sはAの横 rはBの縦 qはAの縦

					seki = A[q][s] * B[s][r];

					sum = sum + seki;



				}

				System.out.print(sum);

				sum = 0;
				if(r != l - 1) {
					System.out.print(" ");
				}


			}

			System.out.println("");
		}

		}



}

