		int[][] ma;
		int[][] mb;

		String x = "";
		try {
			x = in.readLine();
			String[] data = x.split(" ");
			int n = Integer.parseInt(data[0]);
			int m = Integer.parseInt(data[1]);
			int l = Integer.parseInt(data[2]);

