			}

			for (int i = 0; i < m; i++) {
				x = in.readLine();
				data = x.split(" ");

				for (int j = 0; j < l; j++) {
					mb[i][j] = Integer.parseInt(data[j]);
				}
			}

			long[][] mc = new long[n][l];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < l; j++) {
					mc[i][j] = 0;
					for (int k = 0; k < m; k++) {
						mc[i][j] = mc[i][j] + ma[i][k] * mb[k][j];
