	}

	private static void solve(long a, long b, long c, long d) {
		// TODO Auto-generated method stub
		long ans = Long.MIN_VALUE;
		ans = Math.max(ans, a * c);
		ans = Math.max(ans, b * d);
		for (long i = b; i >= a; i--) {
			for (long j = d; j >= c; j--) {
				long t = i * j;
				if (ans > t) break;
				else {
					ans = Math.max(ans, t);
				}
			}
		}
		System.out.println(ans);
	}

}

