        static int MOD = 1000000007;
        public void solve(InputReader in, PrintWriter out){
            long n = in.nextLong();
            int d = 1;
            long cur =26;
            long total = 26;
            while (total < n){
                cur *= 26;
                total += cur;
                d++;
            }
            n -= total / 26;
            String r = "";
            for (int i = 0; i < d; i++){
                int x = (int)(n % 26);
                n /= 26;
                r =  (char)(x +'a')+ r;
