    int x = in.ni(), y = in.ni();
    for (int cranes = 0; cranes <= x; cranes++) {
      int turtles = x - cranes;
      int legs = 2 * cranes;
      int remaining = y - legs;
      if (turtles * 4 == remaining) {
        out.println("Yes");
        return;
      }
    }
    out.println("No");
