			br=new BufferedReader(new InputStreamReader(stream));
			to=new StringTokenizer("");
		}

		String next() {
			while(!to.hasMoreTokens()) {
				try {
					to=new StringTokenizer(br.readLine());	
				}catch(IOException e) {}

			}
			return to.nextToken();

		}

