		Scanner scan = new Scanner(System.in);

		//入力値
		int N = scan.nextInt();
		int[] A = new int[N - 1];

		for (int i = 0; i < N - 1; i++) {
			A[i] = scan.nextInt();
		}

		//WK変数
		SortedMap<Integer, Integer> map = new TreeMap<>();

		for (int i = 0; i < N; i++) {
			map.put(i + 1, 0);
		}

