    static class ATheNumberOfEvenPairs {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int i, j;
            int n = in.ni();
            int m = in.ni();
            int ans = 0;
            ans = n * (n - 1) / 2;
            ans += m * (m - 1) / 2;
            out.println(ans);
        }

