            } else {
                out.println("No");
            }
        }

        private boolean isPalin(String str, int i, int j) {
            int start = i;
            int end = j - 1;

            while (start < end) {
                if (str.charAt(start) != str.charAt(end)) {
                    return false;
                }
                start++;
                end--;
            }

            return true;
        }

    }

    static class FastReader {
