                System.out.println("No");
                return;
            }
        }
        for(int i=len/2+1,j=len-1;i<j;i++,j--){
            if(s.charAt(i)!=s.charAt(j)){
                System.out.println("No");
                return;
            }
        }
        for(int i=0,j=len-1;i<j;i++,j--){
            if(s.charAt(i)!=s.charAt(j)){
                System.out.println("No");
                return;
            }
        }
        System.out.println("Yes");

    }
}

import java.io.PrintWriter;
