        Scanner sc = new Scanner( System.in );
        // 書類の枚数
        int n = sc.nextInt();
        // 両面印刷したときのプリント枚数
        double result = ( double ) n / 2;
        System.out.println( ( int ) Math.ceil( result ) );

        sc.close();
    }
}

