        public bit(int n) {
            this.n=n;
            bit=new long[n+1];
        }
        void add(int ind, int c) {
            for(; ind<=n;ind|=(ind+1)) {
                bit[ind]+=c;
            }
        }
        long sum(int r) {
            long out =0;
            for(;r>=0;r=(r&(r+1))-1) {
