class Solver {
    public void solve(long N, long[] P) {
        long ans = 0;
        long min = Long.MAX_VALUE;
        for (int i = 0; i < N; i++) {
            if (min > P[i]) {
                ans++;
                min = P[i];
            }
        }
        System.out.println(ans);
    }
}

