                map.put(p[i], new int[]{ ++map.get(p[i])[0], map.get(p[i])[1] });
            }
            if ("WA".equals(s[i]) && map.get(p[i])[0] == 0) {
                map.put(p[i], new int[]{map.get(p[i])[0], ++map.get(p[i])[1]});
            }
        }

        int ok = 0;
        int ng = 0;
        for (Map.Entry<Integer, int[]> entry: map.entrySet()) {
            if (entry.getValue()[0] > 0) {
                ok++;
                ng += entry.getValue()[1];
            }
        }

        System.out.println(ok + " " + ng);
