            if ("WA".equals(S)) {
                WA[P]++;
            } else {
                // ACしたとき、この問題でのWAをペナルティとして数える
                AC[P] = true;
                AC_COUNT++;
                WA_COUNT += WA[P];
            }

        }
        System.out.println(AC_COUNT + " " + WA_COUNT);
    }
}

