class Solver {
	int N;
	int cnt;

	public void init() {
		N = 0;
		cnt = 0;
	}

	public void readHead(String str) {
		String[] strArr = str.split("\\s+");
		// N = Integer.parseInt(strArr[0]);
		// System.out.println(N);
		long a = Long.parseLong(strArr[0]);
		long b = Long.parseLong(strArr[1]);
		long k = Long.parseLong(strArr[2]);
		if (a > k) {
			a -= k;
			k = 0;
		} else {
			k -= a;
			a = 0;
		}
		if (b > k) {
			b -= k;
		} else {
