        StringBuilder sb = new StringBuilder();
        String s = arr_temp[0];
        String t = arr_temp[1];

        for (int i = 0; i < n; i++) {
            sb.append(s.substring(i, i + 1));
            sb.append(t.substring(i, i + 1));

        }

        System.out.println(sb);
    }

}

