	}

	public long gcd(long a, long b) {

		if(a > b) {
			long tmp = a;
			a = b;
			b = tmp;
		}

		while(b % a != 0) {

			long tmp = a;
			a = b % a;
			b = tmp;
		}

		return a;
	}
}

