class Solver {
    public void solve(long N, long[] a) {
        int current = 1;
        int ans = 0;
        for (int i = 0; i < N; i++) {
            if (current != a[i]) {
                ans++;
            }
            else {
                current++;
            }
        }
        if (N == ans) {
            System.out.println(-1);
