    public static final ArrayList<Long> divisorX(final long n) {
		final ArrayList<Long> list = new ArrayList<Long>();

		for (long i = 1l; i * i <= n; i++) {
			if (n % i == 0l) {
				list.add(i);
				list.add(n / i);
			}
		}
		return list;
	}
}

