    public static int permutation(int[] q){
        int ret = 0;
        for (int var = 0 ; var < q.length-1 ; var++) {
            for (int var2 = 0; var2 < q.length ;var2++) {
                if(var < var2) ret += q[var] * q[var2];

              //System.out.println(var + " " + var2 +  " " + ret);
            }
        }
        return ret;
    }
}

