		int n = getInt();
		TreeMap<Integer, Integer> ts = new TreeMap<Integer, Integer>();
		for ( int i = 0 ; i < n ; i++ ) {
			ts.put(getInt(), i+1);
		}
		for ( int v: ts.values()) {
			System.out.printf( "%d ", v );
		}
		System.out.println();
	}
}

