		}

		// System.out.println(Arrays.toString(c));

		int res = 0;
		int prev = -1;
		for (int i = 0; i < n; i++) {
			int k = prev + 1;
			if (prev != -1 && prev + 1 == a[i]) {
				res += c[prev - 1]; 
			}
			res += b[a[i] - 1];
			prev = a[i];
		}

		System.out.println(res);
	}

    static class FastReader {
	    BufferedReader br;
	    StringTokenizer st;

	    public FastReader() {
	      br = new BufferedReader(new InputStreamReader(System.in));
	    }

	    String next() { 
	      while (st == null || !st.hasMoreElements()) {
	        try {
	          st = new StringTokenizer(br.readLine());
	        } catch (IOException  e) {
	          e.printStackTrace();
	        }
	      }
	      return st.nextToken();
	    }

	    int nextInt() {
	      return Integer.parseInt(next());
	    }

	    long nextLong() {
	      return Long.parseLong(next());
	    }

	    double nextDouble() { 
	      return Double.parseDouble(next());
	    }

	    String nextLine() {
	      String str = "";
	        try{
	            str = br.readLine();
	        } catch (IOException e) {
	            e.printStackTrace();
	        }
	        return str;
	      }
	  }
}

