class Main{
	public static void main(String[] args) {
		Scanner sc=new Scanner(System.in);
		int N=sc.nextInt();
		HashMap<String,Long> gram=new HashMap();
		long ans=0L;
		for(int i=0; i<N; i++) {
			String s=sc.next();
			char[] c=new char[s.length()];
			c=s.toCharArray();
			Arrays.sort(c);
			String s2=String.valueOf(c);
			if(gram.containsKey(s2)) {
				gram.put(s2,gram.get(s2)+1L);
			}
			else {
				gram.put(s2,1L);
			}
		}

		for(long num : gram.values()) {
			ans+=(num-1)*num/2L;
		}
		p(ans);

	}
	public static void p(Object o) {
		System.out.println(o);
	}
}

import java.util.*;

public class Main {
    public static void main(String args[]) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Map<String, Integer> wordFreq = new HashMap<>();
        for(int i = 0; i < n; i++) {
        	String word = sc.next();
        	char[] arr = word.toCharArray();
        	Arrays.sort(arr);
        	String newWord = new String(arr);
        	wordFreq.put(newWord, wordFreq.getOrDefault(newWord, 0) + 1);
        }
        long res = 0;
        for(Integer freq : wordFreq.values()) {
        	if(freq < 2) continue;
        	res += comb(freq);
        }
        System.out.println(res);
    }

    private static long comb(long a) {
