            HashMap<String, Integer> cnt = new HashMap<>();
            int n = br.nextInt();
            for (int i = 0; i < n; i++) {
                char[] in = br.nextString().toCharArray();
                Arrays.sort(in);
                StringBuilder curr = new StringBuilder();
                for (int j = 0; j < in.length; j++) {
                    curr.append(in[j]);
                }
                if (cnt.containsKey(curr.toString())) {
                    cnt.put(curr.toString(), cnt.get(curr.toString()) + 1);
                } else {
                    cnt.put(curr.toString(), 1);
                }
            }
            long ans = 0;
            for (String curr : cnt.keySet()) {
                Integer val = cnt.get(curr);
                if (val <= 1) {
                    continue;
                }
                ans += C(val, 2);
            }
            pw.println(ans);
            pw.close();
        }

        long C(int n, int k) {
            long res = 1;
            for (int i = n - k + 1; i <= n; ++i)
                res *= i;
            for (int i = 2; i <= k; ++i)
                res /= i;
            return res;
        }

    }

    static class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private FastScanner.SpaceCharFilter filter;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		try (Scanner sc = new Scanner(System.in)) {
			int n = sc.nextInt();
			Map<String, Integer> map = new HashMap<String, Integer>();
			for (int i = 0; i < n; i++) {
				String tmp = change(sc.next());
				if (map.containsKey(tmp)) {
					map.put(tmp, map.get(tmp)+1);
				} else {
					map.put(tmp, 1);
				}
			}
			long result = 0;

			for (String str : map.keySet()) {
				result += calc(map.get(str));
			}
			System.out.println(result);
		}
	}

	private static long calc(long num) {
		return (num * (num - 1)) / 2;
	}

	private static String change(String str) {
		char[] arr = str.toCharArray();
		Arrays.sort(arr);
		return new String(arr);
	}
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {

    void solve() {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        String[] sortedWords = new String[N];
        for (int i = 0; i < N; i++) {
            String word = sc.next();
            char[] tmp = word.toCharArray();
            Arrays.sort(tmp);
            String sortedWord = String.valueOf(tmp);
            sortedWords[i] = sortedWord;
        }

        Map<String, Integer> map = new HashMap();
        for (int i = 0; i < N; i++) {
            map.put(sortedWords[i], new Integer(0));
        }

        for (String sortedWord : sortedWords) {
            int currentCount = map.get(sortedWord);
            map.put(sortedWord, currentCount + 1);
        }
        long ans = 0;
        for (Integer count : map.values()) {
            ans += calcCombination(count, 2);
        }
        System.out.print(ans);
    }

    long calcCombination(int n, int r) {
        if (n < 0 || r < 0) {
            throw new IllegalArgumentException("Arguments must be 0 and over.");
        }
        else if (n == r || r == 0) {
            return 1;
        }
        else if (n < r) {
            return 0;
        }
        else {
            long result = 1;
            for (int i = 1; i <= r; i++) {
                result = result * (n - i + 1) / i;
            }
            return result;
        }
    }

    // Main
    public static void main(String[] args) {
        new Main().solve();
    }
}

