		int h[] = new int[n];

		/* 配列に読み込み */
		for(int i = 0; i < n; i++) {
			h[i] = sc.nextInt();
		}

		int i = 1;
		int j = 1;

		while(i < n) {
			if(h[i-1] <= h[i]) {
				i++;
				continue;
			} else {
				if(j > i) {
					System.out.println("No");
					System.exit(0);
