public class Main {
	public static void main(String[] args) {
		Main main = new Main();
		main.run();
	}

	public void run() {
		Scanner sc = new Scanner(System.in);
		int n=sc.nextInt();
		int a[] = new int[n+1];
		int b[] = new int[n];
		for(int i=0; i<n+1; i++) {
			a[i]=sc.nextInt();
		}
		for(int i=0; i<n; i++) {
			b[i]=sc.nextInt();
		}
		long ans = 0;
		for(int i=0; i<n; i++) {
			int left = Math.min(a[i], b[i]);
			a[i] -= left;
			b[i] -= left;
			ans += left;
			int right = Math.min(a[i+1], b[i]);
			a[i+1] -= right;
			b[i] -= right;
			ans += right;
		}
		System.out.println(ans);
		sc.close();
	}
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int[] A = new int[N + 1];
        for (int i = 0; i < A.length; ++i) {
            A[i] = sc.nextInt();
        }
        int[] B = new int[N];
        for (int i = 0; i < B.length; ++i) {
            B[i] = sc.nextInt();
        }

        System.out.println(solve(A, B));

        sc.close();
    }

    static long solve(int[] A, int[] B) {
        B = Arrays.copyOf(B, B.length + 1);

        long result = 0;
        int extraB = 0;
        for (int i = 0; i < A.length; ++i) {
            int defeatNum = Math.min(A[i], B[i] + extraB);

            result += defeatNum;
            extraB = Math.min(B[i], B[i] + extraB - defeatNum);
        }

        return result;
    }
}

