				second = first;
				first = input;
				first_i = i;

			} else if (second < input) {
				second = input;
			}
		}

		for (int i = 0; i < N; i++ ) {
			if (i == first_i) {
				out.println(second);
			} else {
				out.println(first);
			}
		}

		out.flush();
		sc.close();
	}

}

