  public class Main{
    public static void main(String[]args){
      Scanner sc=new Scanner(System.in);
      while(sc.hasNext()){
      int N=sc.nextInt(); //人数
      int A=sc.nextInt(); //電車を使った時の値段
      int B=sc.nextInt(); //タクシーを使った時の値段
      if(N*A>B){
        System.out.println(B);
      }else{
        System.out.println(N*A);
      }
    }
  }
}

