				if ( sqrt * sqrt == sqSum ) {
					cnt++;
				}
			}
		}

		System.out.println(cnt);
	}

	public static int squareSum(int[] a, int[] b) {
		int sum = 0;
		for ( int d = 0 ; d < a.length ; d++ ) {
			sum += (a[d] - b[d]) * (a[d] - b[d]);
		}
		return sum;
	}

