public class Main {

	public static int min2(int a, int b, int c) {
		int min = Math.min(a, b);
		int min2 = Math.min(b, c);
		int min3 = Math.min(a, c);
		if (min == min2)
			return min3;
		else if (min == min3)
			return min2;
		return min;
	}

