        final Scanner sc = new Scanner(System.in);

        final int N = sc.nextInt();

        final int[] W = new int[N];
        for (int i = 0; i < N; i++) {
            W[i] = sc.nextInt();
        }

        int leftSum = W[0];
        int rightSum = 0;
        for (int i = 1; i < N; i++) {
            rightSum += W[i];
