/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author KharYusuf
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CPrison solver = new CPrison();
        solver.solve(1, in, out);
        out.close();
    }

    static class CPrison {
        public void solve(int testNumber, FastReader s, PrintWriter w) {
            int n = s.nextInt(), m = s.nextInt(), a[] = new int[n + 1], ans = 0;
            for (int i = 0; i < m; i++) {
                a[s.nextInt() - 1]++;
                a[s.nextInt()]--;
            }
            if (a[0] == m) ans++;
            for (int i = 1; i < n; i++) {
                a[i] = a[i - 1] + a[i];
                if (a[i] == m) ans++;
            }
            w.println(ans);
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private FastReader.SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {

            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {

                curChar = 0;

                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0)
                    return -1;
            }

            return buf[curChar++];
        }

        public int nextInt() {

            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;

            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();

                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));

            return res * sgn;
        }

        public boolean isSpaceChar(int c) {

            if (filter != null)
                return filter.isSpaceChar(c);

            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    public static int MAX = 2000000;
    public static int tree[] = new int[MAX];
    public static void update(int qs,int qe,int cs,int ce,int ci){
        if(cs>ce||cs>qe||qs>ce){
            return;
        }
        if(cs>=qs&&ce<=qe){
            //System.out.println(ci);
            tree[ci]++;
            return;
        }
        int mid = (cs+ce)/2;
        update(qs,qe,cs,mid,2*ci+1);
        update(qs,qe,mid+1,ce,2*ci+2);
    }
    public static void lazyPropagation(){
        for(int i=0;i<=MAX/2;i++){
            int v1 = 2*i+1;
            int v2 = 2*i+2;
            if(v1<MAX){
                tree[v1] += tree[i];
            }
            if(v2<MAX){
                tree[v2] += tree[i];
            }
        }
    }
    public static int get(int qs,int qe,int cs,int ce,int ci,int limit){
        if(cs>ce||cs>qe||qs>ce){
            return 0;
        }
        if(cs>=qs&&ce<=qe){
            if(tree[ci]==limit){
                return ce-cs+1;
            }else if(cs==ce){
                return 0;
            }
        }
        int mid = (cs+ce)/2;
        int left = get(qs,qe,cs,mid,2*ci+1,limit);
        int right = get(qs,qe,mid+1,ce,2*ci+2,limit);
        return left+right;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        //int num[] = new int[100001];
        for(int i=0;i<M;i++){
            st = new StringTokenizer(br.readLine());
            int L = Integer.parseInt(st.nextToken());
            int R = Integer.parseInt(st.nextToken());
            //for(int j=L;j<=R;j++){
            //    num[j]++;
            //}
            update(L,R,1,100000,0);
        }
        lazyPropagation();
        int ans = get(1,100000,1,100000,0,M );
        System.out.println(ans);
    }
}

