                    sum += tempB;
                }
                for(int c = 0; c < 5; c++){
                    if(c == a || c == b){
                        continue;
                    }
                    sum += times[c];
                    int tempC = 0;
                    if(sum % 10 != 0){
                        tempC = 10 - sum % 10;
                        sum += tempC;
                    }
                    for(int d = 0; d < 5; d++){
                        if(d == a || d == b || d == c){
                            continue;
                        }
                        sum += times[d];
                        int tempD = 0;
                        if(sum % 10 != 0){
