import java.util.StringTokenizer;

public class Main {
	public static void main(String[] args) {
		FastReader sc = new FastReader();
		String s = sc.next();

		int begin = 0;
		int end = 0;
		int res = 0;

		while (end < s.length()) {
			char c = s.charAt(end);
			if (c == 'A' || c == 'C' || c == 'G' || c == 'T') {
				res = Math.max(res, end - begin + 1);
				end++;
			} else {
				end++;
				begin = end;
			}
		}
		System.out.println(res);
	}

	static class FastReader { 
        BufferedReader br; 
        StringTokenizer st; 

        public FastReader() { 
            br = new BufferedReader(new InputStreamReader(System.in)); 
        } 

        String next() { 
            while (st == null || !st.hasMoreElements()) { 
                try { 
                    st = new StringTokenizer(br.readLine()); 
                } catch (IOException  e) { 
                    e.printStackTrace(); 
                } 
            } 
            return st.nextToken(); 
        } 

        int nextInt() { 
            return Integer.parseInt(next()); 
        } 

        long nextLong() { 
            return Long.parseLong(next()); 
        } 

        double nextDouble() { 
            return Double.parseDouble(next()); 
        } 

        String nextLine() { 
            String str = ""; 
            try{ 
                str = br.readLine(); 
            } catch (IOException e) { 
                e.printStackTrace(); 
            } 
            return str; 
        } 
    } 
}

