    // ======================================================================
    // 2 <= N <= 10^5 : 文字列の長さ　　1 <= Q <= 10^5 : 質問の数
    // 1 <= lq, rq <= N  : 範囲(lq - rq) 
    //
    // 指定された範囲にある文字列　AC の数は？
    // 
    // 普通に文字列検索で行うと間に合わない　→　平方分割にしようとしたが、バグがあり、通らない
    //   →　解説で累積和を使えと言われて
    //
    static class Solver {

    	// 累積和
    	int[] C = null;		// 添え字までに、いくつの　ＡＣ　が含まれるかを保存する

    	public void solve(int testNumber, MyInput in, PrintWriter out) {
        	int ans = 0;
        	int N = in.nextInt();
        	int Q = in.nextInt();
    		String S = in.nextString();
    		C = new int[N];

    		int cnt = 0;					//　累積和の初期設定
    		for(int i=0; i < N; i++) {
    			if(S.charAt(i) == 'A' && (i+1) < N && S.charAt(i+1) == 'C') {
    				C[i] = cnt;
    				C[i+1] = ++cnt;
//    				out.println(" 1   C[" + i + "] = " + C[i]);
//    				out.println(" 2   C[" + (i+1) + "] = " + C[i+1]);
    				i++;
    			} else {
    				C[i] = cnt;
//    				out.println(" 3   C[" + i + "] = " + C[i]);
    			}
    		}

    		int l, r;
    		for(int i=0; i < Q; i++) {
    			l = in.nextInt();
    			r = in.nextInt();
        		out.println(C[r-1] - C[l-1]);
    		}
        }
    }
    // ======================================================================
    static class Pair<K, V> extends AbstractMap.SimpleEntry<K, V> {
        /** serialVersionUID. */
        private static final long serialVersionUID = 6411527075103472113L;

        public Pair(final K key, final V value) {
            super(key, value);
        }
     }    
    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public String nextString() {
        	String ret = new String(nextDChar()).trim();
            return ret;
        }

        public char[] nextDChar() {
            int len = 0;
            len = reads(len, isSpace);
            char[] ret = new char[len + 1];
            for (int i=0; i < len; i++)		ret[i] = str[i];
            ret[len] = 0x00;
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }
    }
}

