      } else {
        if(t == 1) {
          q = i - 1;
          t = 0;
          int[] hana2 = new int[q - p + 1];
          for(int j = 0; j < q - p + 1; j++) { 
            hana2[j] = hana[j + p];
          }
          ans += dfs(hana2);
