	public static int minCostJump(int N, int[] H) {
		int[] cache = new int[N+1];

		cache[2] = Math.abs(H[1] - H[2]);
		for(int i = 3; i <= N; i++) {
			cache[i] = Math.min(cache[i-1] + Math.abs(H[i-1] - H[i]), cache[i-2] + Math.abs(H[i-2]-H[i]));
		}

		return cache[N];
	}
}

