    }

    private void run() {

        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        stones = new int[N];
        int[] dp = new int[N];

        for (int i = 0; i < N; i++) stones[i] = sc.nextInt();

        dp[N-1] = 0;
        dp[N-2] = getDist(N-1, N-2);

        for (int i = N-3; i >= 0; i--) {
            int hop1 = dp[i+1] + getDist(i,i+1);
            int hop2 = dp[i+2] + getDist(i,i+2);
            dp[i] = Math.min(hop1, hop2);
        }

        System.out.println(dp[0]);
    }
