public class Main {
    public static int minCost(int[] h, int i, int[] dp, int k) {
        if (i == 0) {
            return 0;
        }

        int cost = Integer.MAX_VALUE;
        if (dp[i] == -1) {
            for (int j = 1; j <= k; j++) {
                if (i - j >= 0) {
                    cost = Integer.min(cost, minCost(h, i - j, dp, k) + Math.abs(h[i] - h[i - j]));
                }
            }
            dp[i] = cost;
        }
        return dp[i];
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            int size = scanner.nextInt();
            int k = scanner.nextInt();
            int[] h = new int[size];
            for (int i = 0; i < h.length; i++) {
                h[i] = scanner.nextInt();
            }
            int[] dp = new int[size];
            Arrays.fill(dp, -1);
            System.out.println(minCost(h, h.length - 1, dp, k));

        } finally {
            scanner.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
	public static void main(String[] args) throws IOException{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] S = br.readLine().split(" ");
		int N = Integer.parseInt(S[0]);
		int K = Integer.parseInt(S[1]);
		int[] H = new int[N+1];

		S = br.readLine().split(" ");
		for(int i = 0; i < N ; i++) {
			H[i+1] = Integer.parseInt(S[i]);
		}
		System.out.println(minCostJump(N, K, H));
	}

	public static int minCostJump(int N, int K, int[] H) {
		int[] cache = new int[N+1];

		for(int i = 2; i <= N; i++) {
			cache[i] = cache[i-1] + Math.abs(H[i-1] - H[i]);
			for(int j = i-2; j >= i-K && j > 0; j--) {
				cache[i] = Math.min(cache[i], cache[j] + Math.abs(H[j]-H[i]));
			}
		}

		return cache[N];
	}
}

