class AtCoder {

    final int N, T;
    Map<Integer,Integer> map;
    AtCoder(FastScanner sc) {
        N = sc.nextInt();
        T = sc.nextInt();
        map = new TreeMap<>();
        for (int i = 0; i < N; i++) {
            int c = sc.nextInt();
            int t = sc.nextInt();
            map.put(c, t);
        }
    }

    void solve(PrintWriter out) {
        for (Map.Entry<Integer, Integer> e : map.entrySet()) {
            int c = e.getKey();
            int t = e.getValue();
            if (t <= T) {
                out.println(c);
                return;
            }
        }
        out.println("TLE");
    }

}

