    AtCoder(FastScanner sc) {
        S = sc.next();
    }

    void solve(PrintWriter out) {
        char c = S.charAt(0);
        for (int i = 1; i < S.length(); i++) {
            if (S.charAt(i) > c) {
                c++;
                out.println(c+""+c+""+c);
