		{
			int b = Math.max(y,z);
			cost=cost+Math.abs(b-a);

			cost=cost+(Math.max(y,z)-b);

		}
		else if(a==y)
		{
			int b = Math.max(x,z);
			cost=cost+Math.abs(b-a);

			cost=cost+(Math.max(x,z)-b);

		}
		else if(a==z)
		{
			int b = Math.max(x,y);
			cost=cost+Math.abs(b-a);

			cost=cost+(Math.max(x,y)-b);
		}

