            if (X > Y) {
                sum = C * Y * 2;

                if (A < C * 2) {
                    sum += (X - Y) * A;
                } else {
                    sum += (X - Y) * C * 2;
                }
            } else {
                sum = C * X * 2;

                if (B < C * 2) {
                    sum += (Y - X) * B;
                } else {
                    sum += (Y - X) * C * 2;
                }
            }
        } else {
            sum = A * X + B * Y;
        }

