	public static boolean check(String sen) {
        int minIdx = 0;
        int maxIdx = sen.length() - 1;

        while(minIdx < maxIdx) {
            if(sen.charAt(minIdx++) != sen.charAt(maxIdx--)) {
                return false;
            }
        }
        return true;
    }
}

