    }

    static int solve(int A, int B, int C, int X) {
        int result = 0;
        for (int i = 0; i <= A; ++i) {
            for (int j = 0; j <= B; ++j) {
                for (int k = 0; k <= C; ++k) {
                    if (i * 500 + j * 100 + k * 50 == X) {
                        ++result;
                    }
                }
            }
        }

        return result;
    }
}

