        for (int i = 0; i < N ; i++) {
            count[i] = A1[i] + A2[i];
        }
        System.out.println( IntStream.of(count).max().getAsInt());
    }
}

import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

/*
 * AtCoder Beginner Contest 087 C "Candies"
 *   https://abc087.contest.atcoder.jp/tasks/arc090_a/
 */
public class Main {

	public static void main(String[] args) {

		InputScanner in = new InputScanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		int N = in.nextInt();
		int[][] A = in.nextIntArray(2, N);

		int sum1 = A[0][0];
		int sum2 = 0;
		for (int i = 0; i < N; i++) {
			sum2 += A[1][i];
		}

		int ans = sum1 + sum2;
		for (int i = 1; i < N; i++) {
			sum1 += A[0][i];
			sum2 -= A[1][i - 1];
			ans = Math.max(ans, sum1 + sum2);
		}

		out.println(ans);

		in.close();
		out.close();
	}

