			point.add(Integer.parseInt(txy[2]));
			points.add(point);
		}

		for (int i = 1; i < n + 1; i++) {
			List<Integer> current = points.get(i - 1);
			List<Integer> target = points.get(i);
			int manhattan = manhattanDist(current.get(1), current.get(2), target.get(1), target.get(2));
