    int minEven = 0;
    while(numbers[0] %2 == 0){
      numbers[0] = numbers[0] /2;
      minEven++;
    }
    //2つ目以降の数は1つ目より２で割り切れるか？
    for(int j = 1; j<number; j++){
      for(int i = 0; i < minEven; i++){
        if(numbers[j] % 2 != 0){
          minEven = i;
          break;
        }
        else{numbers[j] = numbers[j] /2;}
      }
    }
    System.out.println(minEven);
  }
}

