  public static class Solver {
    public Solver() {

      String S = sc.next();
      int[] nums = new int[4];
      long sum = 0;
      for (int i=0; i<4; i++) {
        nums[i] = S.charAt(i) - '0';
        sum += nums[i];
      }

      for (Bit bit = new Bit(); !bit.get(3); bit.next()) {
        long ans = sum;
        for (int i = bit.nextSetBit(0); i>=0; i=bit.nextSetBit(i+1)) {
          ans -= 2 * nums[i+1];
        }
        if (ans == 7) {
          out.print(nums[0]);
          for (int i=0; i<3; i++) {
            out.print(bit.get(i) ? "-" : "+");
            out.print(nums[i+1]);
          }
          out.println("=7");
          return;
        }
      }

    }

    public class Bit extends BitSet {

      public void set(long l) {
        clear();
        for (int i=0; i<64; i++) {
          if (((l>>i)&1) == 1) set(i, true);
        }
      }

      public long toLong() {
        long res = 0;
        for (int i = nextSetBit(0); i >= 0; i = nextSetBit(i+1)) {
          res += 1<<i;
        }
        return res;
      }

      public void next() {
        for (int i=0; ; i++) {
          if (get(i)) {
            set(i, false);
          } else {
            set(i, true);
            break;
          }
        }
      }

    }

  }

