		int[] a = new int[N];
		sc.fill(a);

		Set<Integer> used = new HashSet<>();
		int next = a[0];
		int count = 1;
		do {
			if (next == 2) {
				System.out.println(count);
				return;
			}

			count++;
			next = a[next - 1];
		} while (used.add(next));

		System.out.println(-1);
