public class Main {
    public static void main(String[] args) throws Exception {
		Scanner sc = new Scanner(System.in);

		// 入力
		String s = sc.next();

		// 計算
		int result = 0;
		int indexA = 0;
		int indexZ = 0;
		boolean flg = true;
