		StringBuilder sb = new StringBuilder();

		for(char c : s.toCharArray()) {
			if(c == '0') {
				sb.append(0);
			}else if(c == '1'){
				sb.append(1);
			}else{
				if(sb.length() != 0) {
					sb.deleteCharAt(sb.length()-1);
				}
			}
		}

		out.println(sb.toString());
	}

	public static int gcd(int a, int b) {
		if(a < b) return gcd(b, a);
		if(b == 0) return a;
		return gcd(b, a % b);
	}

	public static long gcd(long a, long b) {
		if(a < b) return gcd(b, a);
		if(b == 0) return a;
		return gcd(b, a % b);
	}
}

